% This test file was generated by Copilot. Validate generated output before use.
classdef TestFitVirtualSensor < matlab.unittest.TestCase
    methods(Test)
        function testFitsModelAndReturnsExpectedFields(testCase)
            % Verify the function fits a model and returns the expected structure fields.
            numRows = 30;
            flightData = localCreateFlightData(numRows);
            warning("off","MATLAB:rankDeficientMatrix")
            model = fitVirtualSensor(flightData);
            warning("on","MATLAB:rankDeficientMatrix")
            testCase.verifyClass(model, "struct");
            testCase.verifyTrue(isfield(model, "PredictorNames"));
            testCase.verifyTrue(isfield(model, "Coefficients"));
            testCase.verifyTrue(isfield(model, "PredictedTrueAirSpeed"));
            testCase.verifyTrue(isfield(model, "RMSE"));
            testCase.verifyTrue(isfield(model, "TestRows"));
            testCase.verifyTrue(isfield(model, "TopPredictors"));

            testCase.verifyEqual(numel(model.PredictorNames), 9);
            testCase.verifySize(model.Coefficients, [10 1]);
            testCase.verifySize(model.PredictedTrueAirSpeed, [numRows 1]);
            testCase.verifyClass(model.RMSE, "double");
            testCase.verifyGreaterThanOrEqual(model.RMSE, 0);
            testCase.verifyEqual(numel(model.TopPredictors), 3);
        end

        function testNotEnoughValidDataThrowsExpectedError(testCase)
            % Verify that the function errors when fewer than 20 valid rows are available.
            numRows = 19;
            flightData = localCreateFlightData(numRows);

            testCase.verifyError(@() fitVirtualSensor(flightData), "flightDemo:NotEnoughData");
        end
    end
end

function flightData = localCreateFlightData(numRows)
predictorNames = ["FuelQuantity", "OilPressure", "OilTemperature", "Altitude", ...
    "ExhaustTemperature", "FuelFlow", "FanSpeed", "WindDirection", "WindSpeed"];

t = (1:numRows)';
flightData = table;
flightData.FuelQuantity = 100 + 0.5 * t;
flightData.OilPressure = 200 + 0.2 * t;
flightData.OilTemperature = 50 + 0.1 * t;
flightData.Altitude = 1000 + 10 * t;
flightData.ExhaustTemperature = 300 + 0.3 * t;
flightData.FuelFlow = 20 + 0.05 * t;
flightData.FanSpeed = 1000 + 2 * t;
flightData.WindDirection = mod(15 * t, 360);
flightData.WindSpeed = 5 + 0.1 * t;

% Create a deterministic target that depends on predictors.
X = flightData{:, predictorNames};
weights = (1:numel(predictorNames))';
flightData.TrueAirSpeed = 150 + X * weights / 1000;
end